// Validate session_id shape before it reaches a Postgres ::uuid cast
// (an invalid cast throws). Runs right after Webhook.
const webhookJson = $input.first().json;
const body = webhookJson.body || webhookJson || {};
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const session_id = (typeof body.session_id === 'string' && uuidRe.test(body.session_id)) ? body.session_id : null;
return [{ json: { session_id } }];

// Booking slot extraction — build the OpenAI request (Code node).
// Input : webhook body { query, website_url, session_id? } (read via named
//         reference since LookupClinic/FindOpenBooking sit between Webhook
//         and this node, so $input here is FindOpenBooking's row, not the
//         webhook payload). Also sees any already-collected slots for this
//         session so the model can fill gaps rather than re-asking.
// Output: { query, website_url, session_id, has_open, oai_body }
const webhookJson = $('Webhook').first().json;
const body = webhookJson.body || webhookJson || {};
const query = String(body.query || '').trim();
if (!query) throw new Error('query is required');

const session_id = $('EnsureSession').first().json.id;

const openRows = $('FindOpenBooking').all().map(function (i) { return i.json; });
const open = (openRows.length && openRows[0].id != null) ? openRows[0] : null;

const today = new Date().toISOString().slice(0, 10);
const priorLine = open
  ? 'ALREADY COLLECTED THIS CONVERSATION (do not lose these unless the new message changes them): ' +
    JSON.stringify({ service_name: open.service_name, preferred_date: open.preferred_date, preferred_time: open.preferred_time, patient_name: open.patient_name, patient_contact: open.patient_contact }) + '\n'
  : '';

// The model extracts WHAT was said about the date, not a computed date -
// relative-date arithmetic ("next Monday" -> an actual calendar date) is
// done deterministically in parse_slots.js instead. An LLM doing that math
// itself was verified to get it wrong (resolved "next Monday" a week off).
const sys = [
  "Extract a dental/orthodontic appointment request from the patient's message.",
  'Do NOT compute or resolve any date yourself. If the message states an explicit calendar date ' +
    '("July 25th", "8/25", "the 25th"), put it in "explicit_date" as YYYY-MM-DD (today is ' + today + ', use it only to fill in an implied year/month, never to do weekday math). ' +
    'If the message uses relative/day-of-week language ("next Monday", "tomorrow", "this Friday", "Monday"), ' +
    'put the phrase VERBATIM (lowercase) in "relative_day_phrase" and leave "explicit_date" null - do not convert it to a date yourself.',
  priorLine + 'Return ONLY the NEW information found in the LATEST message below (leave a field null if this specific message does not mention it - prior values are merged in separately, do not repeat them).',
  'JSON shape: { "service_name": string|null, "explicit_date": "YYYY-MM-DD"|null, "relative_day_phrase": string|null, "preferred_time": "HH:MM"|null (24h), "patient_name": string|null, "patient_contact": string|null }',
  'Do not invent values not implied by the message.',
].join('\n');

return [{
  json: {
    query, website_url: body.website_url, session_id, has_open: !!open,
    oai_body: {
      model: 'gpt-4o-mini',
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: sys },
        { role: 'user', content: 'LATEST MESSAGE: ' + query },
      ],
    },
  },
}];

// Parse extracted booking slots, MERGE with any already-open booking for
// this session, decide status, prep DB params (Code node).
// Input : OpenAI response (from BuildBookingReq's oai_body).
const req = $('BuildBookingReq').first().json;
const query = req.query;
const clinicRows = $('LookupClinic').all().map(function (i) { return i.json; });
const clinic = clinicRows.length ? clinicRows[0] : null;
const openRows = $('FindOpenBooking').all().map(function (i) { return i.json; });
const open = (openRows.length && openRows[0].id != null) ? openRows[0] : null;

let slots = {};
try { slots = JSON.parse($input.first().json.choices[0].message.content); } catch (e) { slots = {}; }

// Resolve relative-date phrases ("next Monday", "tomorrow") ourselves with
// real Date arithmetic rather than trusting the LLM's math - verified the
// LLM alone gets this wrong (resolved "next Monday" a week off). The model
// only extracts the phrase (build_extract_req.js); this does the computing.
const WEEKDAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
function resolveRelativeDate(phrase, todayStr) {
  if (!phrase) return null;
  const p = String(phrase).toLowerCase();
  const today = new Date(todayStr + 'T00:00:00Z');
  const fmt = function (d) { return d.toISOString().slice(0, 10); };
  const addDays = function (d, n) { const r = new Date(d.getTime()); r.setUTCDate(r.getUTCDate() + n); return r; };

  if (/\btoday\b/.test(p)) return fmt(today);
  if (/\btomorrow\b/.test(p)) return fmt(addDays(today, 1));

  const dayIdx = WEEKDAYS.findIndex(function (w) { return p.indexOf(w) !== -1; });
  if (dayIdx === -1) return null; // an unrecognized phrase - leave null rather than guess

  const todayIdx = today.getUTCDay();
  let diff = (dayIdx - todayIdx + 7) % 7; // 0 = today, 1-6 = the closest upcoming occurrence
  if (diff === 0 && !/\bthis\b/.test(p)) diff = 7; // "monday"/"next monday" said ON a monday means next week's, unless "this monday"
  return fmt(addDays(today, diff));
}
const today = new Date().toISOString().slice(0, 10);
const resolvedDate = slots.explicit_date || resolveRelativeDate(slots.relative_day_phrase, today);

// New values win when present this turn; otherwise carry forward the
// already-collected ones from the open booking (if any).
const service_name = slots.service_name || (open && open.service_name) || null;
const preferred_date = resolvedDate || (open && open.preferred_date) || null;
const preferred_time = slots.preferred_time || (open && open.preferred_time) || null;
const patient_name = slots.patient_name || (open && open.patient_name) || null;
const patient_contact = slots.patient_contact || (open && open.patient_contact) || null;

const missing = [];
if (!service_name) missing.push('service');
if (!preferred_date && !preferred_time) missing.push('preferred date or time');
if (!patient_name) missing.push('your name');

const status = missing.length === 0 ? 'confirming' : 'collecting';

return [{
  json: {
    query,
    booking_id: open ? open.id : null,
    is_update: !!open,
    clinic_id: clinic ? clinic.id : null,
    clinic_name: clinic ? clinic.name : null,
    clinic_phone: clinic ? clinic.phone : null,
    clinic_booking_url: clinic ? clinic.booking_url : null,
    session_id: req.session_id,
    service_name, preferred_date, preferred_time, patient_name, patient_contact,
    status, missing,
  },
}];

// Format the final booking reply (Code node), after InsertBooking wrote the row.
const s = $('ParseSlots').first().json;
const inserted = $input.first().json; // { id, status } from InsertBooking

const contactBits = [];
if (s.clinic_phone) contactBits.push('call ' + s.clinic_phone);
if (s.clinic_booking_url) contactBits.push('book online at ' + s.clinic_booking_url);
const contactLine = contactBits.length ? ' You can also ' + contactBits.join(' or ') + '.' : '';

let answer;
if (s.status === 'confirming') {
  const when = [s.preferred_date, s.preferred_time].filter(Boolean).join(' at ');
  answer = 'Got it' + (s.patient_name ? ', ' + s.patient_name : '') + '! I\'ve noted your request for ' +
    (s.service_name || 'an appointment') + (when ? ' on ' + when : '') +
    '. The clinic will confirm your appointment shortly.' + contactLine;
} else {
  const asks = [];
  if (s.missing.indexOf('service') !== -1) asks.push('which service or treatment you need');
  if (s.missing.indexOf('preferred date or time') !== -1) asks.push('a preferred date or time');
  if (s.missing.indexOf('your name') !== -1) asks.push('your name');
  answer = 'I can help book that. Could you tell me ' + asks.join(' and ') + '?' + contactLine;
}

return [{
  json: {
    query: s.query,
    booking_id: inserted.id,
    status: inserted.status,
    answer,
  },
}];
